import json
from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import FlickerURI


class FlickerV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_supported_bmc_setting(self, node_id, timeout=60):
        uri = FlickerURI().flicker_bmc_uri + "/list/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_supported_bios_setting_list(self, node_id, timeout=60):
        uri = FlickerURI().flicker_bios_uri + "/list/" + node_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def get_bios_setting_with_given_setting_name(self, node_id, setting_name, timeout=60):
        uri = FlickerURI().flicker_bios_uri + "/" + node_id + "/" + setting_name
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def change_bios_setting(self, node_id, target_setting_name, new_setting_value, timeout=60):
        body = {"node_id": node_id,
                "name": target_setting_name,
                "value": new_setting_value}
        uri = FlickerURI().flicker_bios_uri
        headers = {"Content-Type": "application/json"}
        return self.api_client.send_post_request(uri=uri, data=json.dumps(body), headers=headers, timeout=timeout)

    def get_server_led_status(self, node_id, led_id, timeout=60):
        uri = f"{FlickerURI().flicker_led_uri}/{node_id}/{led_id}"
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def set_server_led_status(self, node_id, led_id, value, timeout=60, **kwargs):
        data = {"node_id": node_id,
                "led_id": led_id,
                "value": value}
        if kwargs.get("duration"):
            data["duration"] = kwargs["duration"]
        uri = FlickerURI().flicker_led_uri
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)


